/*
 * EnfCalc — perfis das classes terapêuticas (texto próprio, conhecimento farmacológico consolidado).
 * Chave: código da classe (CMED/EphMRA). Campos: mec (mecanismo/atuação), ae (efeitos adversos comuns),
 * enf (cuidados e monitorização de enfermagem), alerta (riscos graves e interações importantes).
 * O perfil descreve a CLASSE; cada medicamento pode ter particularidades — consultar a bula.
 */
(function (root) {
  'use strict';
  var P = {
    // ---------- Sistema nervoso ----------
    N3A: { mec: 'Reduzem a excitabilidade neuronal por bloqueio de canais de sódio ou cálcio, aumento da ação do GABA ou redução do glutamato, conforme o fármaco.', ae: 'Sonolência, tontura, ataxia, diplopia, náuseas; alguns causam exantema, alterações hematológicas ou hepáticas.', enf: 'Administrar em horários regulares (falhas precipitam crises); avaliar sedação e risco de queda; observar pele nas primeiras semanas; orientar não suspender abruptamente.', alerta: 'Reações cutâneas graves (lamotrigina, carbamazepina, fenitoína); teratogenicidade (valproato); muitas interações por indução/inibição enzimática.' },
    N2A: { mec: 'Agonistas dos receptores opioides (principalmente mu) no sistema nervoso central, reduzindo a transmissão e a percepção da dor.', ae: 'Constipação, náuseas, sonolência, prurido, retenção urinária, depressão respiratória.', enf: 'Avaliar dor, sedação (escala) e frequência respiratória antes e após doses; laxante profilático desde o início; naloxona disponível.', alerta: 'Alta vigilância: depressão respiratória, sobretudo com benzodiazepínicos e álcool; tolerância e dependência; medicamentos controlados.' },
    N2B2: { mec: 'Analgésicos e antitérmicos de ação central e periférica (inibição de prostaglandinas), sem efeito anti-inflamatório relevante (paracetamol, dipirona).', ae: 'Geralmente bem tolerados; reações alérgicas; hepatotoxicidade com doses altas de paracetamol; hipotensão e agranulocitose rara com dipirona.', enf: 'Respeitar dose máxima diária e intervalos; verificar se há outros produtos com o mesmo princípio (associações); reavaliar dor e febre.', alerta: 'Paracetamol acima de 4 g/dia (ou menos em hepatopatas/etilistas) causa insuficiência hepática; dipirona: alergia a pirazolonas.' },
    N2B1: { mec: 'Analgésicos não opioides de venda sob prescrição (ex.: cetorolaco), com inibição da síntese de prostaglandinas.', ae: 'Dispepsia, sangramento, retenção hídrica, piora da função renal.', enf: 'Uso pelo menor tempo; hidratar; observar sangramento e diurese.', alerta: 'Evitar em sangramento ativo, úlcera, insuficiência renal e com anticoagulantes.' },
    N2C1: { mec: 'Triptanos: agonistas dos receptores serotoninérgicos 5-HT1B/1D, causam vasoconstrição craniana e inibem a liberação de neuropeptídeos inflamatórios.', ae: 'Sensação de aperto no peito ou garganta, formigamento, rubor, tontura.', enf: 'Usar no início da crise; não repetir antes do intervalo da bula; registrar frequência das crises.', alerta: 'Contraindicados em doença coronariana, AVC e hipertensão não controlada; síndrome serotoninérgica com ISRS/IRSN.' },
    N2D: { mec: 'Gabapentinoides: ligam-se à subunidade alfa-2-delta dos canais de cálcio, reduzindo a liberação de neurotransmissores excitatórios.', ae: 'Tontura, sonolência, edema periférico, ganho de peso, visão turva.', enf: 'Titular gradualmente; risco de queda; ajustar pela função renal.', alerta: 'Depressão respiratória com opioides; potencial de abuso; não suspender abruptamente.' },
    N1A2: { mec: 'Anestésicos gerais injetáveis (propofol, cetamina, etomidato, tiopental) que induzem perda de consciência por ação em receptores GABA-A ou NMDA.', ae: 'Hipotensão, apneia, dor à injeção; cetamina: alucinações e hipertensão; etomidato: mioclonias e supressão adrenal.', enf: 'Somente com monitorização contínua, via aérea e material de reanimação; técnica asséptica rigorosa (propofol favorece crescimento bacteriano).', alerta: 'Alta vigilância: depressão respiratória e cardiovascular; síndrome de infusão do propofol em doses altas prolongadas.' },
    N1B1: { mec: 'Anestésicos locais: bloqueiam canais de sódio dos nervos, impedindo a condução do impulso doloroso.', ae: 'Dor/ardor local; em níveis tóxicos: gosto metálico, zumbido, formigamento perioral, convulsões e arritmias.', enf: 'Aspirar antes de injetar; respeitar a dose máxima por peso (com ou sem vasoconstritor).', alerta: 'Toxicidade sistêmica (convulsões, parada cardíaca) — emulsão lipídica 20% é o antídoto; vasoconstritor contraindicado em extremidades conforme orientação.' },
    N1B3: { mec: 'Anestésicos locais de uso tópico em pele e mucosas.', ae: 'Irritação local; absorção sistêmica em grandes áreas.', enf: 'Aplicar a quantidade e o tempo indicados (ex.: antes de punções); retirar após o procedimento.', alerta: 'Metemoglobinemia com benzocaína/prilocaína, sobretudo em lactentes.' },
    N5A1: { mec: 'Antipsicóticos atípicos: bloqueio de receptores dopaminérgicos D2 e serotoninérgicos 5-HT2A.', ae: 'Ganho de peso, alterações metabólicas (glicemia, lipídios), sedação, hipotensão postural; menos sintomas extrapiramidais que os típicos.', enf: 'Monitorar peso, glicemia, PA e sinais extrapiramidais; avaliar sedação; adesão.', alerta: 'Aumento de mortalidade em idosos com demência; prolongamento do QT; síndrome neuroléptica maligna (febre, rigidez).' },
    N5A9: { mec: 'Antipsicóticos convencionais (típicos): bloqueio potente de receptores dopaminérgicos D2.', ae: 'Sintomas extrapiramidais (distonia, acatisia, parkinsonismo), sedação, hipotensão, efeitos anticolinérgicos.', enf: 'Observar distonia aguda (biperideno disponível); ECG em doses altas; prevenir queda.', alerta: 'Síndrome neuroléptica maligna; prolongamento do QT (haloperidol EV); discinesia tardia no uso prolongado.' },
    N5B1: { mec: 'Hipnóticos não barbitúricos (ex.: zolpidem, eszopiclona) que potencializam o GABA em receptores benzodiazepínicos.', ae: 'Sonolência residual, tontura, amnésia, comportamentos complexos durante o sono.', enf: 'Administrar ao deitar com tempo suficiente de sono; avaliar risco de queda em idosos.', alerta: 'Depressão do SNC com álcool e opioides; dependência; medicamentos controlados.' },
    N5C: { mec: 'Tranquilizantes (principalmente benzodiazepínicos): aumentam a ação inibitória do GABA no receptor GABA-A.', ae: 'Sonolência, ataxia, déficit de memória, fraqueza; reação paradoxal em idosos e crianças.', enf: 'Avaliar sedação e risco de queda; não suspender abruptamente após uso prolongado; flumazenil disponível em uso EV.', alerta: 'Depressão respiratória com opioides e álcool; dependência e abstinência; evitar em idosos (critérios de Beers).' },
    N6A4: { mec: 'Antidepressivos ISRS: inibem a recaptação de serotonina na fenda sináptica.', ae: 'Náuseas, cefaleia, insônia ou sonolência, disfunção sexual, hiponatremia em idosos.', enf: 'Efeito em 2–4 semanas; orientar adesão; observar ideação suicida no início (jovens); não suspender abruptamente.', alerta: 'Síndrome serotoninérgica com tramadol, triptanos, linezolida, IMAO; sangramento com AINE/anticoagulantes; QT (citalopram, escitalopram).' },
    N6A5: { mec: 'Antidepressivos IRSN: inibem a recaptação de serotonina e noradrenalina.', ae: 'Náuseas, sudorese, aumento da PA, insônia, disfunção sexual.', enf: 'Monitorar PA; orientar não suspender abruptamente (síndrome de descontinuação).', alerta: 'Síndrome serotoninérgica; hipertensão dose-dependente; sangramento.' },
    N6A9: { mec: 'Antidepressivos de outros mecanismos (bupropiona, trazodona, mirtazapina, vortioxetina, agomelatina etc.).', ae: 'Variam: sedação e ganho de peso (mirtazapina, trazodona); insônia e convulsões (bupropiona); náuseas (vortioxetina).', enf: 'Observar humor, sono e efeitos específicos de cada fármaco; adesão.', alerta: 'Ideação suicida no início; síndrome serotoninérgica; bupropiona reduz o limiar convulsivo.' },
    N6B: { mec: 'Psicoestimulantes: aumentam a disponibilidade de dopamina e noradrenalina.', ae: 'Insônia, perda de apetite, taquicardia, aumento da PA, irritabilidade.', enf: 'Administrar pela manhã; monitorar PA, FC, peso e crescimento (crianças).', alerta: 'Medicamentos controlados com potencial de abuso; cautela em cardiopatias.' },
    N4A: { mec: 'Antiparkinsonianos: repõem dopamina (levodopa), estimulam receptores dopaminérgicos ou reduzem sua degradação (IMAO-B, COMT).', ae: 'Náuseas, hipotensão postural, discinesias, alucinações, sonolência súbita.', enf: 'Horários rigorosos (atrasos pioram a rigidez); levodopa longe de refeições proteicas; prevenir quedas.', alerta: 'Não suspender abruptamente (síndrome semelhante à neuroléptica maligna); comportamentos compulsivos com agonistas.' },
    N7D1: { mec: 'Inibidores da colinesterase: aumentam a acetilcolina cerebral (donepezila, rivastigmina, galantamina).', ae: 'Náuseas, vômitos, diarreia, perda de peso, bradicardia, síncope.', enf: 'Titulação lenta; administrar com alimento; observar FC; adesivo: trocar diariamente e retirar o anterior.', alerta: 'Bradicardia e bloqueios cardíacos; cautela em asma e úlcera péptica.' },
    N7A: { mec: 'Imunomoduladores e imunossupressores para esclerose múltipla.', ae: 'Reações no local da injeção, sintomas gripais, alterações hepáticas e hematológicas, infecções.', enf: 'Rodízio dos locais de aplicação; monitorar exames laboratoriais conforme protocolo.', alerta: 'Infecções oportunistas (inclusive leucoencefalopatia multifocal progressiva com alguns agentes).' },
    // ---------- Cardiovascular ----------
    C10A1: { mec: 'Estatinas: inibem a enzima HMG-CoA redutase, reduzindo a síntese de colesterol no fígado e o LDL.', ae: 'Mialgia, elevação de transaminases, dispepsia; raramente rabdomiólise.', enf: 'Orientar relatar dor muscular sem causa e urina escura; adesão contínua.', alerta: 'Rabdomiólise com claritromicina, azólicos, ciclosporina e fibratos (genfibrozila); contraindicadas na gestação.' },
    C10A2: { mec: 'Fibratos: ativam o receptor PPAR-alfa, reduzindo triglicerídeos e aumentando o HDL.', ae: 'Dispepsia, mialgia, elevação de creatinina, colelitíase.', enf: 'Monitorar função renal e sintomas musculares.', alerta: 'Miopatia associada a estatinas; potencializam anticoagulantes orais.' },
    C9A: { mec: 'Inibidores da ECA: bloqueiam a conversão de angiotensina I em II, causando vasodilatação e redução da aldosterona.', ae: 'Tosse seca, hipotensão, hipercalemia, elevação da creatinina.', enf: 'Monitorar PA (primeira dose), potássio e creatinina; orientar sobre tosse.', alerta: 'Angioedema (emergência); contraindicados na gestação; hipercalemia com espironolactona e suplementos de potássio.' },
    C9C: { mec: 'Bloqueadores dos receptores AT1 da angiotensina II (BRA): vasodilatação e redução da aldosterona.', ae: 'Tontura, hipotensão, hipercalemia, elevação da creatinina; não causam tosse como os IECA.', enf: 'Monitorar PA, potássio e função renal.', alerta: 'Contraindicados na gestação; não associar IECA + BRA; hipercalemia com poupadores de potássio.' },
    C9D1: { mec: 'Associação de BRA com diurético ou outro anti-hipertensivo.', ae: 'Os de cada componente: hipotensão, distúrbios de sódio e potássio.', enf: 'Monitorar PA, eletrólitos e função renal.', alerta: 'Contraindicadas na gestação.' },
    C7A0: { mec: 'Betabloqueadores: bloqueiam receptores beta-adrenérgicos, reduzindo FC, contratilidade e PA.', ae: 'Bradicardia, fadiga, extremidades frias, broncoespasmo (não seletivos), disfunção sexual.', enf: 'Verificar FC e PA antes da dose; não suspender abruptamente (rebote de taquicardia e isquemia).', alerta: 'Mascaram sinais de hipoglicemia; cautela em asma/DPOC, bloqueios AV; associação com verapamil/diltiazem.' },
    C8A: { mec: 'Bloqueadores dos canais de cálcio: di-hidropiridinas (anlodipino, nifedipino) causam vasodilatação; não di-hidropiridinas (verapamil, diltiazem) reduzem FC e condução AV.', ae: 'Edema de tornozelos, cefaleia, rubor (di-hidropiridinas); bradicardia e constipação (verapamil).', enf: 'Monitorar PA e FC; não triturar formas de liberação prolongada.', alerta: 'Nifedipino de liberação imediata sublingual é contraindicado (hipotensão brusca); verapamil/diltiazem com betabloqueadores: bradicardia grave.' },
    C3A2: { mec: 'Diuréticos de alça: inibem o cotransportador Na-K-2Cl na alça de Henle, com diurese potente.', ae: 'Hipopotassemia, hiponatremia, hipovolemia, hipotensão, ototoxicidade em doses altas.', enf: 'Pesar diariamente; balanço hídrico; monitorar potássio e PA; administrar pela manhã.', alerta: 'Desidratação e distúrbios eletrolíticos em idosos; ototoxicidade com aminoglicosídeos.' },
    C3A3: { mec: 'Diuréticos tiazídicos e análogos: inibem o cotransportador Na-Cl no túbulo distal.', ae: 'Hipopotassemia, hiponatremia, hiperuricemia, hiperglicemia.', enf: 'Administrar pela manhã; monitorar sódio, potássio e glicemia.', alerta: 'Hiponatremia grave em idosos; podem precipitar gota.' },
    C1E: { mec: 'Nitratos: doadores de óxido nítrico que causam venodilatação (reduzem a pré-carga) e dilatação coronariana.', ae: 'Cefaleia, hipotensão, taquicardia reflexa, rubor.', enf: 'Paciente sentado ao usar sublingual; verificar PA; respeitar intervalo livre de nitrato (tolerância).', alerta: 'CONTRAINDICADOS com sildenafila/tadalafila (hipotensão grave); cautela no infarto de ventrículo direito.' },
    C1B: { mec: 'Antiarrítmicos: atuam em canais iônicos ou receptores para restaurar ou controlar o ritmo cardíaco.', ae: 'Bradicardia, hipotensão, pró-arritmia; amiodarona: tireoide, pulmão, fígado e pele.', enf: 'Monitorização eletrocardiográfica; observar flebite (amiodarona EV); controle de QT.', alerta: 'Alta vigilância em uso EV; risco de arritmias graves (torsades).' },
    C1A1: { mec: 'Digitálicos: inibem a bomba Na/K-ATPase, aumentando a contratilidade e reduzindo a condução AV.', ae: 'Náuseas, vômitos, alterações visuais (amarelada), arritmias na intoxicação.', enf: 'Verificar FC apical por 1 min antes da dose; monitorar potássio e função renal.', alerta: 'Janela terapêutica estreita; intoxicação favorecida por hipopotassemia, insuficiência renal e amiodarona.' },
    C2A2: { mec: 'Anti-hipertensivos de ação periférica, como os bloqueadores alfa-1 (doxazosina, prazosina).', ae: 'Hipotensão postural (especialmente na primeira dose), tontura, cefaleia.', enf: 'Primeira dose ao deitar; orientar levantar devagar.', alerta: 'Síncope de primeira dose; síndrome da íris flácida em cirurgia de catarata.' },
    C1C1: { mec: 'Estimulantes cardíacos (adrenérgicos como noradrenalina, adrenalina, dobutamina) que aumentam a contratilidade e/ou o tônus vascular.', ae: 'Taquiarritmias, isquemia, hipertensão, necrose por extravasamento.', enf: 'Bomba de infusão, acesso exclusivo (preferência central), monitorização contínua e titulação pela PAM.', alerta: 'Alta vigilância: extravasamento (vesicantes); nunca interromper bruscamente.' },
    // ---------- Sangue ----------
    B1F: { mec: 'Inibidores diretos do fator Xa (rivaroxabana, apixabana, edoxabana).', ae: 'Sangramentos, anemia, dispepsia.', enf: 'Respeitar horários; orientar sinais de sangramento; checar função renal; suspensão antes de procedimentos conforme protocolo.', alerta: 'Alta vigilância: sangramento grave; não associar outros anticoagulantes; interações com azólicos, rifampicina e anticonvulsivantes indutores.' },
    B1C2: { mec: 'Antiagregantes inibidores do receptor P2Y12 (clopidogrel, ticagrelor, prasugrel).', ae: 'Sangramento, equimoses; ticagrelor: dispneia.', enf: 'Orientar não suspender sem o cardiologista (trombose de stent); sinais de sangramento.', alerta: 'Sangramento com anticoagulantes e AINE; suspensão pré-operatória conforme protocolo.' },
    B3A1: { mec: 'Sais de ferro para reposição dos estoques e síntese de hemoglobina.', ae: 'Náuseas, epigastralgia, constipação, fezes escuras; EV: reações de hipersensibilidade.', enf: 'Oral longe de laticínios e antiácidos (vitamina C favorece absorção); EV com observação após a infusão.', alerta: 'Intoxicação por ferro em crianças (armazenar fora do alcance).' },
    B2D1: { mec: 'Concentrados de fator VIII de coagulação (hemofilia A).', ae: 'Reações alérgicas, desenvolvimento de inibidores.', enf: 'Reconstituir conforme fabricante, sem agitar; registrar lote; dose por UI/kg conforme protocolo.', alerta: 'Hemoderivado/biológico: rastreabilidade obrigatória.' },
    B2D2: { mec: 'Concentrados de fatores II, VII, IX e X (complexo protrombínico) e afins.', ae: 'Trombose, reações alérgicas.', enf: 'Infundir na velocidade do fabricante; coletar INR após.', alerta: 'Risco trombótico; dose conforme INR e protocolo.' },
    // ---------- Anti-infecciosos ----------
    J1D2: { mec: 'Cefalosporinas injetáveis: betalactâmicos que inibem a síntese da parede bacteriana.', ae: 'Reações alérgicas, flebite, diarreia (C. difficile), alteração de provas hepáticas.', enf: 'Investigar alergia a betalactâmicos; respeitar horários (antibiótico tempo-dependente); reconstituição e diluição conforme a ficha.', alerta: 'Ceftriaxona + cálcio (precipitação); reatividade cruzada em alergia grave à penicilina.' },
    J1D1: { mec: 'Cefalosporinas orais: betalactâmicos que inibem a parede bacteriana.', ae: 'Diarreia, náuseas, reações alérgicas.', enf: 'Completar o tratamento; respeitar intervalos; observar diarreia.', alerta: 'Alergia a betalactâmicos.' },
    J1C1: { mec: 'Penicilinas orais de amplo espectro (amoxicilina, ampicilina) que inibem a parede bacteriana.', ae: 'Diarreia, exantema, candidíase.', enf: 'Investigar alergia; completar o tratamento; amoxicilina com clavulanato junto às refeições.', alerta: 'Anafilaxia em alérgicos.' },
    J1C2: { mec: 'Penicilinas injetáveis de amplo espectro (ampicilina, piperacilina-tazobactam).', ae: 'Reações alérgicas, flebite, diarreia, distúrbios eletrolíticos.', enf: 'Investigar alergia; respeitar estabilidade após reconstituição; infusão no tempo indicado.', alerta: 'Anafilaxia; incompatibilidades em Y com aminoglicosídeos.' },
    J1H1: { mec: 'Penicilinas de pequeno e médio espectro (benzilpenicilina, oxacilina).', ae: 'Reações alérgicas; benzatina: dor local intensa; reação de Jarisch-Herxheimer na sífilis.', enf: 'Benzatina: IM profunda em glúteo, nunca EV; observar 30 min após a aplicação.', alerta: 'Anafilaxia; penicilina benzatina EV pode ser fatal.' },
    J1F: { mec: 'Macrolídeos (azitromicina, claritromicina, eritromicina): inibem a síntese proteica bacteriana (ribossomo 50S).', ae: 'Náuseas, diarreia, dor abdominal, alteração do paladar.', enf: 'Respeitar o esquema (azitromicina tem dias curtos de tratamento); EV diluído e lento.', alerta: 'Prolongamento do QT; claritromicina interage com estatinas, colchicina e outros (CYP3A4).' },
    J1G1: { mec: 'Fluoroquinolonas: inibem DNA-girase e topoisomerase IV bacterianas.', ae: 'Náuseas, tontura, fotossensibilidade, alterações glicêmicas.', enf: 'Separar de antiácidos, ferro, cálcio e zinco; hidratação.', alerta: 'Tendinite e ruptura de tendão, prolongamento do QT, neuropatia, confusão em idosos; uso reservado.' },
    J1P2: { mec: 'Carbapenêmicos: betalactâmicos de amplo espectro, resistentes à maioria das betalactamases.', ae: 'Diarreia, flebite, reações alérgicas; convulsões (imipenem).', enf: 'Infusão conforme estabilidade; uso guiado pela CCIH.', alerta: 'Reduzem drasticamente o nível de valproato; reservar para multirresistentes.' },
    J1K: { mec: 'Aminoglicosídeos: inibem a síntese proteica bacteriana (ribossomo 30S), ação concentração-dependente.', ae: 'Nefrotoxicidade, ototoxicidade, bloqueio neuromuscular.', enf: 'Dose única diária em geral; monitorar creatinina, diurese e audição; níveis séricos quando indicados.', alerta: 'Toxicidade aumentada com vancomicina, furosemida e contraste.' },
    J1X1: { mec: 'Glicopeptídeos (vancomicina, teicoplanina): inibem a parede de Gram-positivos.', ae: 'Reação à infusão rápida (rubor), nefrotoxicidade, flebite.', enf: 'Infundir lentamente (≥ 60 min por grama); monitorar creatinina e nível sérico.', alerta: 'Síndrome do homem vermelho; nefrotoxicidade com aminoglicosídeos.' },
    J1X2: { mec: 'Polimixinas (polimixina B, colistina): rompem a membrana de Gram-negativos.', ae: 'Nefrotoxicidade, neurotoxicidade (parestesias, fraqueza).', enf: 'Monitorar creatinina e diurese; uso guiado pela CCIH.', alerta: 'Bloqueio neuromuscular com relaxantes musculares; reservar para multirresistentes.' },
    J1E: { mec: 'Sulfametoxazol + trimetoprima: bloqueio sequencial da síntese de folato bacteriano.', ae: 'Exantema, náuseas, hipercalemia, alterações hematológicas.', enf: 'Hidratação; observar pele e potássio.', alerta: 'Síndrome de Stevens-Johnson; potencializa varfarina; hipercalemia com IECA/BRA.' },
    J1A: { mec: 'Tetraciclinas (doxiciclina, minociclina): inibem a síntese proteica bacteriana.', ae: 'Esofagite, fotossensibilidade, náuseas.', enf: 'Tomar com copo cheio de água e não deitar por 30 min; separar de cálcio, ferro e antiácidos.', alerta: 'Evitar em gestantes e crianças < 8 anos (dentes e ossos).' },
    J2A: { mec: 'Antifúngicos sistêmicos (azólicos, equinocandinas, anfotericina) que alteram a membrana ou a parede fúngica.', ae: 'Hepatotoxicidade (azólicos), nefrotoxicidade e reações à infusão (anfotericina).', enf: 'Monitorar função hepática e renal; anfotericina com pré-hidratação conforme protocolo.', alerta: 'Azólicos interagem com muitos fármacos (estatinas, midazolam, anticoagulantes) e prolongam o QT.' },
    J5B3: { mec: 'Antivirais para herpes (aciclovir, valaciclovir): inibem a DNA-polimerase viral.', ae: 'Náuseas, cefaleia; nefrotoxicidade e confusão em doses EV altas.', enf: 'Hidratação adequada; EV em 1 h; ajustar pela função renal.', alerta: 'Cristalúria e lesão renal com infusão rápida ou desidratação.' },
    J7B1: { mec: 'Vacinas com componente antitetânico: induzem imunidade ativa contra a toxina tetânica.', ae: 'Dor e edema local, febre baixa.', enf: 'Conferir caderneta e calendário; IM no deltoide (ou vasto lateral em crianças); registrar lote.', alerta: 'Rede de frio (2–8 °C); notificar eventos adversos.' },
    // ---------- Respiratório e alergia ----------
    R6A: { mec: 'Anti-histamínicos H1: bloqueiam a ação da histamina nos receptores H1.', ae: '1ª geração: sedação e efeitos anticolinérgicos; 2ª geração: pouca sedação.', enf: 'Orientar sobre sonolência (1ª geração); evitar em idosos (anticolinérgicos).', alerta: 'Não substituem a adrenalina na anafilaxia.' },
    R5C: { mec: 'Expectorantes e mucolíticos: fluidificam ou facilitam a eliminação da secreção.', ae: 'Desconforto gastrointestinal, náuseas.', enf: 'Aumentar ingestão de líquidos; conferir a concentração do xarope (adulto × pediátrico).', alerta: 'Mucolíticos não devem ser usados em menores de 2 anos.' },
    R3F1: { mec: 'Associação de beta-2 agonista de longa ação com corticoide inalatório (asma e DPOC).', ae: 'Candidíase oral, rouquidão, tremor, taquicardia.', enf: 'Revisar técnica inalatória; enxaguar a boca após o uso.', alerta: 'Não usar beta-2 de longa ação isolado na asma.' },
    R1A1: { mec: 'Corticoides nasais: reduzem a inflamação da mucosa nasal.', ae: 'Epistaxe, ressecamento e irritação nasal.', enf: 'Técnica: cabeça levemente inclinada, jato para a lateral da narina; efeito em dias.', alerta: 'Uso prolongado em crianças: acompanhar crescimento.' },
    R3B2: { mec: 'Xantinas (aminofilina, teofilina): broncodilatação e estímulo respiratório.', ae: 'Náuseas, taquicardia, insônia, arritmias e convulsões em níveis altos.', enf: 'Monitorar FC e sinais de toxicidade; EV lento.', alerta: 'Janela terapêutica estreita; muitas interações (ciprofloxacino, eritromicina).' },
    // ---------- Digestivo ----------
    A2B2: { mec: 'Inibidores da bomba de prótons: bloqueiam a H+/K+-ATPase das células parietais, reduzindo a secreção ácida.', ae: 'Cefaleia, diarreia; uso prolongado: hipomagnesemia, deficiência de B12, fraturas, infecção por C. difficile.', enf: 'Oral 30–60 min antes do café; reavaliar necessidade de uso prolongado.', alerta: 'Omeprazol reduz o efeito do clopidogrel; desprescrever quando não indicado.' },
    A3F: { mec: 'Procinéticos (metoclopramida, bromoprida, domperidona): aceleram o esvaziamento gástrico (antagonismo dopaminérgico).', ae: 'Sonolência, sintomas extrapiramidais (metoclopramida/bromoprida), diarreia.', enf: 'EV lento; observar distonia (biperideno disponível).', alerta: 'Discinesia tardia no uso prolongado; domperidona prolonga o QT.' },
    A3A: { mec: 'Antiespasmódicos e anticolinérgicos: relaxam a musculatura lisa do trato gastrointestinal.', ae: 'Boca seca, taquicardia, retenção urinária, constipação, visão turva.', enf: 'Observar retenção urinária e confusão em idosos.', alerta: 'Contraindicados em glaucoma de ângulo fechado e obstrução intestinal.' },
    A6A2: { mec: 'Laxantes estimulantes: aumentam o peristaltismo e a secreção intestinal.', ae: 'Cólicas, diarreia, distúrbios eletrolíticos no uso abusivo.', enf: 'Preferir à noite; associar hidratação e fibras.', alerta: 'Contraindicados em suspeita de obstrução intestinal.' },
    A4A1: { mec: 'Antieméticos antagonistas 5-HT3 (ondansetrona, granisetrona).', ae: 'Cefaleia, constipação.', enf: 'Pode ser EV direto lento ou diluído; via oral orodispersível sem água.', alerta: 'Prolongamento do QT (cautela com outros fármacos que prolongam QT); síndrome serotoninérgica rara.' },
    A10H: { mec: 'Sulfonilureias: estimulam a secreção de insulina pelo pâncreas.', ae: 'Hipoglicemia, ganho de peso.', enf: 'Administrar com o café da manhã; orientar sinais de hipoglicemia e não pular refeições.', alerta: 'Hipoglicemia prolongada em idosos e na insuficiência renal.' },
    A10N1: { mec: 'Inibidores da DPP-4 (gliptinas): aumentam as incretinas, elevando a insulina e reduzindo o glucagon de forma glicose-dependente.', ae: 'Nasofaringite, cefaleia; raramente pancreatite.', enf: 'Pouco risco de hipoglicemia isoladamente; ajuste renal (exceto linagliptina).', alerta: 'Dor abdominal intensa: avaliar pancreatite.' },
    A10P1: { mec: 'Inibidores do SGLT2 (glifozinas): aumentam a excreção urinária de glicose; benefício cardiorrenal.', ae: 'Infecção genital, poliúria, hipotensão, desidratação.', enf: 'Hidratação; higiene íntima; suspender em doença aguda com jejum e antes de cirurgias.', alerta: 'Cetoacidose euglicêmica (glicemia normal ou pouco elevada).' },
    A10C1: { mec: 'Insulinas de ação rápida/ultrarrápida (regular, lispro, asparte, glulisina).', ae: 'Hipoglicemia, lipodistrofia no local.', enf: 'Conferir tipo e dose (dupla checagem); aplicar próximo às refeições conforme o tipo; rodízio de locais.', alerta: 'Alta vigilância: hipoglicemia grave; nunca usar "U" para unidades em prescrições.' },
    A10C5: { mec: 'Insulinas de ação longa (glargina, detemir, degludeca): cobertura basal.', ae: 'Hipoglicemia, ganho de peso.', enf: 'Mesmo horário diário; não misturar com outras insulinas; conferir concentração (100 × 300 U/mL).', alerta: 'Alta vigilância; não usar por via EV.' },
    A10S: { mec: 'Agonistas do receptor GLP-1: aumentam a insulina, reduzem glucagon, retardam o esvaziamento gástrico e reduzem o apetite.', ae: 'Náuseas, vômitos, diarreia, constipação.', enf: 'Orientar refeições menores; aplicação SC conforme frequência (diária ou semanal).', alerta: 'Pancreatite; risco de aspiração em sedação/anestesia (estômago cheio).' },
    A2A1: { mec: 'Antiácidos: neutralizam o ácido gástrico.', ae: 'Constipação (alumínio), diarreia (magnésio).', enf: 'Separar de outros medicamentos por 2 h (reduzem absorção).', alerta: 'Cautela com magnésio e alumínio na insuficiência renal.' },
    // ---------- Musculoesquelético ----------
    M1A1: { mec: 'Anti-inflamatórios não esteroidais (AINE): inibem as cicloxigenases (COX-1 e COX-2), reduzindo prostaglandinas.', ae: 'Dispepsia, úlcera e sangramento GI, retenção hídrica, aumento da PA, lesão renal.', enf: 'Administrar com alimento; menor dose pelo menor tempo; observar sangramento e diurese.', alerta: 'Evitar em insuficiência renal, cardíaca, úlcera, gestação no 3º trimestre e com anticoagulantes; risco cardiovascular.' },
    M1A3: { mec: 'Coxibes: inibidores seletivos da COX-2 (menor agressão gástrica).', ae: 'Edema, aumento da PA, dispepsia, lesão renal.', enf: 'Monitorar PA; menor dose pelo menor tempo.', alerta: 'Aumento de risco cardiovascular (infarto, AVC); evitar em cardiopatia isquêmica.' },
    M3B: { mec: 'Relaxantes musculares de ação central: deprimem reflexos polissinápticos na medula e tronco.', ae: 'Sonolência, tontura, boca seca.', enf: 'Orientar sobre sedação e risco de queda; uso por curto prazo.', alerta: 'Potencializam álcool, benzodiazepínicos e opioides.' },
    M3A: { mec: 'Relaxantes musculares de ação periférica (bloqueadores neuromusculares e toxina botulínica).', ae: 'Fraqueza muscular; bloqueadores: paralisia respiratória.', enf: 'Bloqueadores neuromusculares só com via aérea garantida e sedação adequada; identificar seringas.', alerta: 'Alta vigilância: paralisia respiratória.' },
    M5B3: { mec: 'Bisfosfonatos: inibem a reabsorção óssea pelos osteoclastos.', ae: 'Esofagite (oral), sintomas gripais (EV), hipocalcemia.', enf: 'Oral: jejum, copo cheio de água, 30 min em pé sem alimento; corrigir cálcio e vitamina D.', alerta: 'Osteonecrose de mandíbula; fratura atípica de fêmur; ajustar na insuficiência renal.' },
    M4A: { mec: 'Antigotosos: reduzem ácido úrico (alopurinol, febuxostate) ou a inflamação da crise (colchicina).', ae: 'Exantema (alopurinol), diarreia (colchicina).', enf: 'Hidratação; não iniciar hipouricemiante em plena crise sem profilaxia.', alerta: 'Síndrome de hipersensibilidade ao alopurinol; toxicidade da colchicina com claritromicina e azólicos.' },
    M2A: { mec: 'Anti-inflamatórios e analgésicos de uso tópico.', ae: 'Irritação e fotossensibilidade local.', enf: 'Aplicar em pele íntegra; lavar as mãos após.', alerta: 'Absorção sistêmica em grandes áreas.' },
    // ---------- Pele, olhos, hormônios ----------
    D7A: { mec: 'Corticoides tópicos: anti-inflamatórios e antipruriginosos.', ae: 'Atrofia cutânea, estrias, telangiectasias, acne.', enf: 'Camada fina; tempo limitado; evitar face e dobras com corticoides potentes.', alerta: 'Supressão adrenal com uso extenso ou oclusivo, sobretudo em crianças.' },
    D6A: { mec: 'Antibióticos tópicos para infecções cutâneas superficiais.', ae: 'Irritação e dermatite de contato.', enf: 'Limpar a lesão antes; uso por tempo limitado.', alerta: 'Resistência bacteriana com uso prolongado.' },
    D1A1: { mec: 'Antifúngicos tópicos (azólicos, alilaminas).', ae: 'Irritação local.', enf: 'Aplicar além da borda da lesão; manter por 1–2 semanas após a melhora; manter a área seca.', alerta: 'Micose de unha e couro cabeludo geralmente exige tratamento oral.' },
    S1E2: { mec: 'Antiglaucomatosos tópicos: reduzem a pressão intraocular diminuindo a produção ou aumentando a drenagem do humor aquoso.', ae: 'Ardor, hiperemia; prostaglandinas: escurecimento da íris e cílios longos.', enf: 'Ocluir o ponto lacrimal 1–2 min após a gota; intervalo de 5 min entre colírios; não tocar o frasco no olho.', alerta: 'Betabloqueadores em colírio: bradicardia e broncoespasmo (absorção sistêmica).' },
    S1K1: { mec: 'Lágrimas artificiais e lubrificantes oculares.', ae: 'Visão borrada transitória (géis).', enf: 'Preferir sem conservante em uso frequente.', alerta: 'Sintomas persistentes exigem avaliação oftalmológica.' },
    H2A1: { mec: 'Corticoides injetáveis: anti-inflamatórios e imunossupressores potentes.', ae: 'Hiperglicemia, retenção hídrica, insônia, euforia, imunossupressão.', enf: 'Monitorar glicemia; administrar pela manhã quando possível; IM profunda nas suspensões.', alerta: 'Não suspender abruptamente após uso prolongado (insuficiência adrenal).' },
    H2A2: { mec: 'Corticoides orais: anti-inflamatórios e imunossupressores.', ae: 'Hiperglicemia, aumento da PA, osteoporose, ganho de peso, alterações de humor.', enf: 'Administrar pela manhã com alimento; monitorar glicemia e PA.', alerta: 'Desmame gradual após mais de 2–3 semanas de uso.' },
    G2A: { mec: 'Uterotônicos e indutores do parto (ocitocina e análogos).', ae: 'Taquissistolia, náuseas, hiponatremia (doses altas).', enf: 'Bomba de infusão; monitorar contrações e frequência cardíaca fetal.', alerta: 'Alta vigilância: hiperestimulação uterina e ruptura.' },
    G4E1: { mec: 'Inibidores da fosfodiesterase-5: aumentam o GMPc, causando vasodilatação.', ae: 'Cefaleia, rubor, congestão nasal, dispepsia.', enf: 'Perguntar sempre sobre nitratos.', alerta: 'CONTRAINDICADOS com nitratos (hipotensão grave).' },
    G3A9: { mec: 'Contraceptivos hormonais sistêmicos (injetáveis, implantes, orais isolados).', ae: 'Alteração do padrão de sangramento, cefaleia, mastalgia.', enf: 'Orientar horários/datas de aplicação e uso de método adicional se atraso.', alerta: 'Interações com indutores enzimáticos (rifampicina, anticonvulsivantes).' },
    L3A1: { mec: 'Fatores estimuladores de colônias: estimulam a produção de neutrófilos.', ae: 'Dor óssea, reação local.', enf: 'Manter refrigerado; aplicar SC conforme protocolo do ciclo.', alerta: 'Ruptura esplênica rara (dor em ombro esquerdo/abdome).' },
    L4X: { mec: 'Imunossupressores (ex.: tacrolimo, micofenolato, everolimo).', ae: 'Infecções, alterações renais, metabólicas e hematológicas.', enf: 'Horários rigorosos; níveis séricos quando indicados; precauções contra infecção.', alerta: 'Muitas interações (azólicos, macrolídeos, indutores); teratogenicidade (micofenolato).' },
    K1D2: { mec: 'Emulsões lipídicas para nutrição parenteral: fonte de energia e ácidos graxos essenciais.', ae: 'Hipertrigliceridemia, febre, reações alérgicas.', enf: 'Técnica asséptica; equipo exclusivo e filtro conforme protocolo; respeitar tempo de infusão.', alerta: 'Alergia a ovo/soja; síndrome de sobrecarga lipídica.' },
    // ---------- Ampliação: diabetes, anticoagulação, diuréticos, hormônios ----------
    A10J1: { mec: 'Biguanidas (metformina): reduzem a produção hepática de glicose e aumentam a sensibilidade à insulina.', ae: 'Náuseas, diarreia, gosto metálico, deficiência de vitamina B12 no uso prolongado.', enf: 'Administrar com as refeições; titulação gradual reduz efeitos GI; verificar função renal.', alerta: 'Acidose lática (rara): suspender antes de contraste iodado e em desidratação, choque ou insuficiência renal grave.' },
    A10N3: { mec: 'Associação de inibidor da DPP-4 com metformina.', ae: 'Os de cada componente: náuseas e diarreia (metformina), nasofaringite.', enf: 'Administrar com refeições; checar função renal.', alerta: 'Suspender metformina antes de contraste iodado e em instabilidade clínica.' },
    B1B1: { mec: 'Heparina não fracionada: potencializa a antitrombina, inativando trombina e fator Xa.', ae: 'Sangramento, hematoma no local SC, trombocitopenia induzida por heparina (TIH).', enf: 'Dupla checagem; bomba de infusão; TTPa conforme protocolo; plaquetas; SC sem aspirar e sem massagear.', alerta: 'Alta vigilância. Antídoto: protamina. Confundir frascos de 5.000 × 25.000 UI causa erros graves.' },
    B1B2: { mec: 'Heparinas de baixo peso molecular (enoxaparina etc.): inibem predominantemente o fator Xa.', ae: 'Sangramento, hematomas no local, trombocitopenia.', enf: 'SC no abdome, sem expulsar a bolha de ar da seringa pronta e sem massagear; rodízio; ajustar ao peso e à função renal.', alerta: 'Alta vigilância. Hematoma espinhal com anestesia neuroaxial; acúmulo na insuficiência renal.' },
    B1A: { mec: 'Antagonistas da vitamina K (varfarina): reduzem a síntese dos fatores II, VII, IX e X.', ae: 'Sangramentos, equimoses; necrose cutânea rara.', enf: 'Controle de INR; mesmo horário diário; orientar dieta estável em vitamina K e não usar AINE por conta própria.', alerta: 'Alta vigilância: muitas interações (antibióticos, amiodarona, azólicos). Reversão: vitamina K e complexo protrombínico.' },
    B1C1: { mec: 'Antiagregantes inibidores da ciclo-oxigenase (ácido acetilsalicílico em baixa dose): bloqueiam o tromboxano A2 plaquetário.', ae: 'Dispepsia, sangramento GI, equimoses.', enf: 'Administrar após refeição; orientar sinais de sangramento.', alerta: 'Não suspender sem orientação em pacientes com stent; sangramento com anticoagulantes; síndrome de Reye em crianças.' },
    C3A1: { mec: 'Diuréticos poupadores de potássio (espironolactona, amilorida): antagonizam a aldosterona ou bloqueiam canais de sódio no túbulo coletor.', ae: 'Hipercalemia, ginecomastia (espironolactona), alterações menstruais.', enf: 'Monitorar potássio e creatinina; evitar suplementos de potássio sem prescrição.', alerta: 'Hipercalemia grave com IECA, BRA e insuficiência renal.' },
    C2A1: { mec: 'Anti-hipertensivos de ação central (clonidina, metildopa): reduzem o tônus simpático.', ae: 'Sonolência, boca seca, bradicardia, hipotensão postural.', enf: 'Monitorar PA e FC; metildopa é opção na gestação.', alerta: 'Clonidina: hipertensão rebote na suspensão abrupta.' },
    C1F: { mec: 'Inotrópicos positivos não adrenérgicos (ex.: milrinona, levosimendana).', ae: 'Hipotensão, arritmias, cefaleia.', enf: 'Bomba de infusão e monitorização contínua; ajustar pela função renal (milrinona).', alerta: 'Hipotensão importante em hipovolemia; arritmias.' },
    H3A: { mec: 'Hormônios tireoidianos (levotiroxina): reposição no hipotireoidismo.', ae: 'Sinais de excesso: palpitações, tremor, insônia, perda de peso.', enf: 'Em jejum, 30–60 min antes do café, sempre no mesmo horário; separar de cálcio, ferro e antiácidos.', alerta: 'Excesso causa arritmias (idosos, cardiopatas); não usar para emagrecer.' },
    H3B: { mec: 'Antitireoidianos (metimazol, propiltiouracila): inibem a síntese dos hormônios tireoidianos.', ae: 'Exantema, prurido, alteração hepática, agranulocitose rara.', enf: 'Orientar procurar atendimento se febre ou dor de garganta (hemograma).', alerta: 'Agranulocitose; hepatotoxicidade grave com propiltiouracila.' },
    G3D: { mec: 'Progestógenos isolados: anticoncepção, terapia hormonal e suporte de fase lútea.', ae: 'Sangramento irregular, cefaleia, mastalgia, alteração de humor.', enf: 'Orientar horários rigorosos (pílula só de progestógeno) e datas de reaplicação.', alerta: 'Interações com indutores enzimáticos reduzem a eficácia.' },
    G3A: { mec: 'Contraceptivos hormonais combinados (estrógeno + progestógeno): inibem a ovulação.', ae: 'Náuseas, cefaleia, mastalgia, sangramento intermenstrual.', enf: 'Orientar conduta em esquecimento; aferir PA; investigar tabagismo e enxaqueca com aura.', alerta: 'Risco de trombose venosa (maior em fumantes > 35 anos); contraindicados com enxaqueca com aura.' },
    G3B: { mec: 'Andrógenos (testosterona e derivados): reposição hormonal masculina.', ae: 'Acne, policitemia, alterações lipídicas, ginecomastia.', enf: 'IM profunda lenta (soluções oleosas); hematócrito periódico.', alerta: 'Policitemia e eventos trombóticos; uso indevido para desempenho.' },
    G3C: { mec: 'Estrógenos isolados: terapia hormonal da menopausa e outras indicações.', ae: 'Mastalgia, náuseas, sangramento.', enf: 'Orientar consultas periódicas (mamas, PA).', alerta: 'Em mulheres com útero, associar progestógeno (risco endometrial); risco trombótico.' },
    G3G: { mec: 'Gonadotrofinas e estimulantes da ovulação (reprodução assistida).', ae: 'Dor abdominal, distensão, cefaleia.', enf: 'Orientar a técnica de autoaplicação e os horários exatos.', alerta: 'Síndrome de hiperestímulo ovariano.' },
    // ---------- Respiratório ----------
    R3A2: { mec: 'Beta-2 agonistas sistêmicos (salbutamol oral/EV, terbutalina): broncodilatação.', ae: 'Tremor, taquicardia, hipopotassemia, hiperglicemia.', enf: 'Monitorar FC e potássio; preferir via inalatória quando possível.', alerta: 'Arritmias e hipopotassemia em doses altas.' },
    R3D1: { mec: 'Corticoides inalatórios: anti-inflamatórios das vias aéreas (controle da asma).', ae: 'Candidíase oral, rouquidão.', enf: 'Revisar técnica inalatória e espaçador; enxaguar a boca após o uso; uso diário mesmo sem sintomas.', alerta: 'Não servem para alívio imediato da crise.' },
    R3K2: { mec: 'Anticolinérgicos inalatórios de longa ação (LAMA: tiotrópio, glicopirrônio): broncodilatação na DPOC.', ae: 'Boca seca, constipação, retenção urinária.', enf: 'Revisar técnica do dispositivo; uso uma vez ao dia.', alerta: 'Cautela em glaucoma de ângulo fechado e hiperplasia prostática.' },
    R3L2: { mec: 'Associação de anticolinérgico (LAMA) e beta-2 agonista (LABA) de longa ação, inalatória.', ae: 'Boca seca, tremor, taquicardia.', enf: 'Técnica do dispositivo; não usar para crise aguda.', alerta: 'Cautela em arritmias, glaucoma e retenção urinária.' },
    R1A7: { mec: 'Descongestionantes nasais tópicos (vasoconstritores alfa-adrenérgicos).', ae: 'Ardor; congestão rebote.', enf: 'Limitar a 3–5 dias; orientar a não usar continuamente.', alerta: 'Contraindicados em lactentes; rinite medicamentosa e hipertensão com uso abusivo.' },
    R5A: { mec: 'Antigripais: associações de analgésico, anti-histamínico e/ou descongestionante para alívio de sintomas.', ae: 'Sonolência, taquicardia, aumento da PA, boca seca.', enf: 'Checar duplicidade de paracetamol/dipirona com outros medicamentos; orientar sobre sonolência.', alerta: 'Descongestionantes sistêmicos: cautela em hipertensos e cardiopatas; não usar em crianças pequenas.' },
    R2A: { mec: 'Preparações para garganta (antissépticos e anestésicos locais em pastilhas ou spray).', ae: 'Irritação local, dormência.', enf: 'Orientar não comer logo após anestésicos tópicos (risco de aspiração).', alerta: 'Dor de garganta com febre alta ou placas exige avaliação.' },
    // ---------- Digestivo e nutrição ----------
    A2B1: { mec: 'Antagonistas H2 (famotidina, ranitidina): reduzem a secreção ácida gástrica.', ae: 'Cefaleia, tontura; confusão em idosos.', enf: 'Ajustar pela função renal.', alerta: 'Menos potentes que os IBP; confusão mental em idosos com doses altas.' },
    A4A9: { mec: 'Outros antieméticos (dimenidrinato, aprepitanto, escopolamina etc.).', ae: 'Sonolência, boca seca, constipação, conforme o fármaco.', enf: 'Avaliar sedação; administrar antes do fator desencadeante (viagem, quimioterapia).', alerta: 'Anticolinérgicos: confusão e retenção urinária em idosos.' },
    A6A3: { mec: 'Laxantes formadores de bolo (psyllium, fibras): aumentam volume e umidade das fezes.', ae: 'Distensão, flatulência.', enf: 'Tomar com bastante água; separar de outros medicamentos.', alerta: 'Pouca água pode causar obstrução esofágica ou intestinal.' },
    A6A4: { mec: 'Laxantes de uso retal (enemas): estímulo osmótico ou mecânico do reto.', ae: 'Cólica, desconforto local.', enf: 'Decúbito lateral esquerdo; aquecer à temperatura corporal; registrar resultado.', alerta: 'Enemas de fosfato: distúrbios eletrolíticos em crianças, idosos e renais.' },
    A7F: { mec: 'Probióticos (microrganismos vivos) para diarreia e restabelecimento da flora.', ae: 'Distensão e flatulência.', enf: 'Separar do antibiótico por cerca de 2 h (bacterianos); conservar conforme rótulo.', alerta: 'Evitar em imunossuprimidos graves e cateter venoso central (risco de fungemia/bacteremia).' },
    A7G: { mec: 'Sais de reidratação oral: repõem água e eletrólitos (glicose favorece absorção de sódio).', ae: 'Vômitos se ingeridos rápido.', enf: 'Diluir exatamente no volume indicado; oferecer em pequenos goles frequentes; avaliar sinais de desidratação.', alerta: 'Diluição errada causa distúrbios de sódio.' },
    A7A: { mec: 'Anti-infecciosos intestinais de ação local (ex.: nitazoxanida, rifaximina).', ae: 'Náuseas, dor abdominal; urina amarelada (nitazoxanida).', enf: 'Hidratação; administrar com alimento quando indicado.', alerta: 'Diarreia com sangue ou febre alta exige avaliação.' },
    A12A: { mec: 'Sais de cálcio para reposição e prevenção de osteoporose.', ae: 'Constipação, distensão; hipercalcemia.', enf: 'Separar de levotiroxina, ferro, quinolonas e tetraciclinas; carbonato com alimento.', alerta: 'EV: gluconato × cloreto têm doses diferentes; extravasamento causa necrose; incompatível com ceftriaxona.' },
    A11E1: { mec: 'Vitaminas do complexo B.', ae: 'Urina amarelada (riboflavina); raramente reações alérgicas EV.', enf: 'Na suspeita de deficiência de tiamina (etilistas), tiamina antes da glicose.', alerta: 'Encefalopatia de Wernicke precipitada por glicose sem tiamina.' },
    A11F: { mec: 'Vitamina B12 (cianocobalamina, hidroxocobalamina): reposição na deficiência.', ae: 'Dor local; raramente hipopotassemia no início da reposição de anemias graves.', enf: 'IM profunda; orientar esquema de manutenção.', alerta: 'Hidroxocobalamina em dose alta é antídoto do cianeto (outra indicação).' },
    A11A4: { mec: 'Polivitamínicos com minerais: suplementação.', ae: 'Desconforto GI, fezes escuras (ferro).', enf: 'Separar de antibióticos quinolonas e tetraciclinas.', alerta: 'Intoxicação por ferro e vitaminas lipossolúveis em crianças.' },
    K1A7: { mec: 'Ringer e Ringer lactato: soluções cristaloides balanceadas para reposição volêmica.', ae: 'Sobrecarga hídrica, edema.', enf: 'Balanço hídrico; controlar velocidade; observar congestão pulmonar.', alerta: 'Contém cálcio: não infundir com sangue no mesmo equipo nem com ceftriaxona.' },
    K1A3: { mec: 'Soluções eletrolíticas para reposição e manutenção.', ae: 'Distúrbios eletrolíticos e sobrecarga de volume.', enf: 'Conferir composição e velocidade; balanço hídrico.', alerta: 'Eletrólitos concentrados são de alta vigilância.' },
    K1E1: { mec: 'Soluções de aminoácidos para nutrição parenteral.', ae: 'Hiperglicemia (na NP completa), flebite em via periférica com alta osmolaridade.', enf: 'Técnica asséptica; via central conforme osmolaridade; glicemia capilar.', alerta: 'Infecção de cateter; síndrome de realimentação.' },
    K6A: { mec: 'Soluções para hemodiálise e diálise peritoneal.', ae: 'Hipotensão, cãibras, distúrbios eletrolíticos.', enf: 'Técnica asséptica rigorosa; conferir concentração; balanço de entradas e saídas.', alerta: 'Peritonite (efluente turvo, dor abdominal).' },
    // ---------- Anti-infecciosos e vacinas ----------
    J1G2: { mec: 'Fluoroquinolonas injetáveis (ciprofloxacino, levofloxacino, moxifloxacino).', ae: 'Flebite, náuseas, alterações glicêmicas.', enf: 'Infundir em 60 min ou mais; mesma dose oral tem boa biodisponibilidade (transição precoce).', alerta: 'QT longo, tendinopatia, convulsões, confusão em idosos.' },
    J1B: { mec: 'Anfenicóis (cloranfenicol): inibem a síntese proteica bacteriana.', ae: 'Supressão medular, náuseas.', enf: 'Hemograma periódico.', alerta: 'Aplasia medular (rara e grave); síndrome do bebê cinzento em neonatos.' },
    J4A1: { mec: 'Antituberculosos (rifampicina, isoniazida, pirazinamida, etambutol).', ae: 'Hepatotoxicidade, urina e secreções alaranjadas (rifampicina), neuropatia (isoniazida), alteração visual (etambutol).', enf: 'Tratamento diretamente observado; em jejum; orientar sobre a coloração da urina; adesão até o fim.', alerta: 'Rifampicina reduz a eficácia de anticoncepcionais, antirretrovirais e anticoagulantes; hepatite medicamentosa.' },
    J5C: { mec: 'Antirretrovirais: inibem etapas da replicação do HIV (transcriptase reversa, protease, integrase).', ae: 'Náuseas, cefaleia, alterações lipídicas e renais, conforme o fármaco.', enf: 'Adesão rigorosa (horários); nunca interromper por conta própria; checar interações.', alerta: 'Muitas interações (rifampicina, anticonvulsivantes, antiácidos com inibidores de integrase).' },
    J5B9: { mec: 'Outros antivirais (ex.: oseltamivir para influenza).', ae: 'Náuseas, vômitos, cefaleia.', enf: 'Iniciar o mais cedo possível nos casos indicados; administrar com alimento.', alerta: 'Ajuste pela função renal.' },
    J6A1: { mec: 'Soros antiofídicos: anticorpos heterólogos que neutralizam o veneno.', ae: 'Reações precoces (urticária, anafilaxia) e doença do soro tardia.', enf: 'EV conforme o tipo de acidente e a gravidade (Ministério da Saúde); material de reanimação pronto; observar reações.', alerta: 'Anafilaxia: adrenalina disponível. Não fazer torniquete nem incisões no local da picada.' },
    J7: { mec: 'Vacinas: induzem imunidade ativa contra a doença.', ae: 'Dor, rubor e edema local; febre baixa.', enf: 'Conferir calendário e caderneta; via e local corretos; registrar lote; orientar eventos esperados.', alerta: 'Rede de frio (2–8 °C, não congelar); vacinas vivas contraindicadas em imunossuprimidos e gestantes; notificar eventos adversos.' },
    P1D1: { mec: 'Antimaláricos (cloroquina, hidroxicloroquina, primaquina etc.).', ae: 'Náuseas, cefaleia, alterações visuais no uso prolongado.', enf: 'Administrar com alimento; seguir esquema do Ministério da Saúde.', alerta: 'Prolongamento do QT; hemólise com primaquina na deficiência de G6PD.' },
    P1B: { mec: 'Anti-helmínticos (albendazol, mebendazol, ivermectina).', ae: 'Dor abdominal, náuseas, cefaleia.', enf: 'Orientar higiene e tratamento dos contactantes; mastigar comprimidos quando indicado.', alerta: 'Albendazol contraindicado na gestação.' },
    G1B: { mec: 'Antifúngicos ginecológicos (cremes e óvulos vaginais).', ae: 'Ardor e irritação local.', enf: 'Aplicar à noite, deitada; completar o tratamento mesmo menstruada (conforme bula).', alerta: 'Podem danificar preservativos de látex (veículos oleosos).' },
    G1A2: { mec: 'Tricomonicidas e antibacterianos vaginais (metronidazol tópico etc.).', ae: 'Irritação local; gosto metálico.', enf: 'Tratar parceria sexual quando indicado.', alerta: 'Evitar álcool com metronidazol.' },
    // ---------- Pele, olhos, ouvidos ----------
    D3A9: { mec: 'Produtos para tratamento de feridas (desbridantes, cicatrizantes, coberturas).', ae: 'Irritação ou dor local.', enf: 'Escolher o produto pela fase e exsudato da ferida; documentar medidas e aspecto.', alerta: 'Sinais de infecção (calor, odor, secreção purulenta) exigem reavaliação.' },
    D7B1: { mec: 'Corticoide tópico associado a antibacteriano.', ae: 'Atrofia cutânea, dermatite de contato.', enf: 'Tempo limitado; camada fina.', alerta: 'Uso prolongado favorece resistência e efeitos do corticoide.' },
    D7B2: { mec: 'Corticoide tópico associado a antifúngico.', ae: 'Atrofia cutânea, irritação.', enf: 'Uso por curto prazo.', alerta: 'Pode mascarar micoses (tinea incógnita).' },
    D10A: { mec: 'Antiacneicos tópicos (retinoides, peróxido de benzoíla, antibióticos tópicos).', ae: 'Ressecamento, ardor, fotossensibilidade.', enf: 'Aplicar à noite em pele seca; protetor solar.', alerta: 'Retinoides tópicos: evitar na gestação.' },
    D5B: { mec: 'Antipsoríase sistêmicos (metotrexato, acitretina etc.).', ae: 'Náuseas, alterações hepáticas e hematológicas.', enf: 'Exames periódicos; metotrexato é SEMANAL.', alerta: 'Erro diário × semanal do metotrexato é fatal; teratogênicos (acitretina por anos).' },
    D8A1: { mec: 'Antissépticos (clorexidina, iodopovidona, álcool).', ae: 'Irritação e ressecamento da pele.', enf: 'Respeitar o tempo de secagem antes do procedimento; escolher a formulação (degermante, alcoólica, aquosa) pelo local.', alerta: 'Álcool inflamável (eletrocautério); clorexidina não deve entrar em ouvido médio ou meninges.' },
    D2A: { mec: 'Emolientes e protetores cutâneos: restauram a barreira da pele.', ae: 'Raramente irritação.', enf: 'Aplicar após o banho; útil na prevenção de lesões por umidade.', alerta: 'Pele com lesão aberta ou sinais de infecção requer avaliação antes do uso.' },
    S1A: { mec: 'Anti-infecciosos oftálmicos (colírios e pomadas antibióticas/antivirais).', ae: 'Ardor e irritação transitórios.', enf: 'Higienizar as mãos; não encostar o frasco no olho; 5 min entre colírios; pomada por último.', alerta: 'Olho vermelho com dor e baixa visual: encaminhar.' },
    S1B: { mec: 'Corticoides oftálmicos: anti-inflamatórios oculares.', ae: 'Aumento da pressão intraocular, catarata no uso prolongado.', enf: 'Agitar suspensões; não suspender abruptamente após uso prolongado.', alerta: 'Contraindicados em ceratite herpética.' },
    S1C1: { mec: 'Associação oftálmica de corticoide com anti-infeccioso.', ae: 'Ardor, aumento da pressão intraocular.', enf: 'Agitar antes; tempo limitado.', alerta: 'Uso prolongado sem avaliação oftalmológica pode agravar infecções e glaucoma.' },
    S1F: { mec: 'Midriáticos e cicloplégicos (tropicamida, fenilefrina, atropina): dilatam a pupila.', ae: 'Visão turva, fotofobia; efeitos sistêmicos em crianças.', enf: 'Orientar não dirigir após; ocluir o ponto lacrimal.', alerta: 'Podem precipitar glaucoma agudo de ângulo fechado.' },
    S1P: { mec: 'Antiangiogênicos intravítreos (anti-VEGF) para degeneração macular e retinopatias.', ae: 'Dor ocular, hiperemia, moscas volantes.', enf: 'Procedimento asséptico; orientar sinais de alerta após a injeção.', alerta: 'Endoftalmite: dor intensa e piora visual nos dias seguintes exigem atendimento imediato.' },
    S2C: { mec: 'Associações otológicas de corticoide com anti-infeccioso.', ae: 'Prurido e irritação local.', enf: 'Aquecer o frasco nas mãos; cabeça inclinada alguns minutos após as gotas.', alerta: 'Alguns são ototóxicos se a membrana timpânica estiver perfurada.' },
    // ---------- Sistema nervoso e outros ----------
    N1A1: { mec: 'Anestésicos gerais inalatórios (sevoflurano, isoflurano, desflurano).', ae: 'Hipotensão, náuseas e vômitos pós-operatórios, agitação ao despertar.', enf: 'Monitorização na recuperação anestésica; controle de náuseas e dor.', alerta: 'Hipertermia maligna (dantroleno); exposição ocupacional.' },
    N1B2: { mec: 'Anestésicos locais injetáveis odontológicos, geralmente com vasoconstritor.', ae: 'Dormência prolongada, palpitações (vasoconstritor).', enf: 'Orientar não morder lábios e língua enquanto anestesiados (crianças).', alerta: 'Toxicidade sistêmica com doses acima do máximo por peso.' },
    N6A3: { mec: 'Estabilizadores do humor (lítio e afins).', ae: 'Tremor, poliúria, sede, ganho de peso, hipotireoidismo.', enf: 'Litemia conforme protocolo; hidratação e ingestão de sal estáveis; orientar sinais de intoxicação.', alerta: 'Janela terapêutica estreita: intoxicação com desidratação, diuréticos, AINE e IECA.' },
    N5B5: { mec: 'Sedativos fitoterápicos (valeriana, passiflora, melissa).', ae: 'Sonolência, desconforto GI.', enf: 'Perguntar sempre sobre fitoterápicos na anamnese.', alerta: 'Somam efeito a outros depressores do SNC.' },
    N7B: { mec: 'Produtos antitabaco (reposição de nicotina, bupropiona, vareniclina).', ae: 'Náuseas, insônia, sonhos vívidos; irritação local (adesivo/goma).', enf: 'Orientar técnica (goma: mastigar e repousar na bochecha); rodízio do adesivo; apoio comportamental.', alerta: 'Bupropiona reduz o limiar convulsivo; acompanhar humor.' },
    N7C: { mec: 'Antivertiginosos (betaistina, flunarizina, cinarizina, dimenidrinato).', ae: 'Sonolência, ganho de peso, sintomas extrapiramidais (flunarizina/cinarizina em idosos).', enf: 'Risco de queda; uso por tempo limitado na crise.', alerta: 'Parkinsonismo e depressão com uso prolongado de flunarizina/cinarizina em idosos.' },
    N7E: { mec: 'Produtos para dependência alcoólica (naltrexona, dissulfiram, acamprosato).', ae: 'Náuseas, cefaleia; dissulfiram: reação grave com álcool.', enf: 'Orientar abstinência total de álcool (inclusive em xaropes e enxaguantes) com dissulfiram.', alerta: 'Naltrexona bloqueia analgésicos opioides; hepatotoxicidade.' },
    M1A2: { mec: 'Associações de anti-inflamatórios não esteroidais com outros fármacos (relaxantes, vitaminas etc.).', ae: 'Os do AINE (dispepsia, lesão renal) somados aos dos outros componentes.', enf: 'Verificar duplicidade de AINE com outras prescrições.', alerta: 'Mesmo risco renal, GI e cardiovascular dos AINE.' },
    M1B: { mec: 'Associações de corticoide com antirreumáticos ou analgésicos.', ae: 'Hiperglicemia, retenção hídrica, dispepsia.', enf: 'Monitorar glicemia; uso curto.', alerta: 'Corticoide oculto em associações: atenção em diabéticos.' },
    C5C: { mec: 'Vasoprotetores sistêmicos (diosmina, hesperidina, castanha-da-índia).', ae: 'Desconforto GI, cefaleia.', enf: 'Associar medidas posturais e meias de compressão quando indicadas.', alerta: 'Não substituem anticoagulação em trombose.' },
    C4A1: { mec: 'Vasodilatadores periféricos e cerebrais (pentoxifilina, cilostazol etc.).', ae: 'Cefaleia, palpitações, desconforto GI.', enf: 'Administrar com alimento; observar sangramento.', alerta: 'Cilostazol contraindicado na insuficiência cardíaca.' },
    V3C: { mec: 'Radiofármacos: substâncias radioativas para diagnóstico ou terapia.', ae: 'Geralmente mínimos.', enf: 'Seguir normas de radioproteção; orientar hidratação e higiene após o exame.', alerta: 'Gestação e amamentação: avaliar antes do exame.' },
    T1A: { mec: 'Contrastes iodados de baixa osmolaridade para tomografia e angiografia.', ae: 'Calor, náuseas, urticária; nefropatia induzida por contraste.', enf: 'Investigar alergia prévia e função renal; hidratação; observar o local da punção (extravasamento).', alerta: 'Anafilaxia; suspender metformina conforme protocolo.' },
    T1E: { mec: 'Contrastes à base de gadolínio para ressonância magnética.', ae: 'Náuseas, cefaleia, reações alérgicas raras.', enf: 'Checar função renal e alergia prévia; observar após a injeção.', alerta: 'Fibrose sistêmica nefrogênica em insuficiência renal grave (agentes lineares).' },
    // ---------- Oncologia e imunobiológicos ----------
    L1: { mec: 'Antineoplásicos: interferem na divisão ou nas vias de sinalização das células tumorais.', ae: 'Náuseas, mielossupressão, mucosite, alopecia, fadiga (variam conforme o agente).', enf: 'Dupla checagem de dose e superfície corporal; EPI e manuseio seguro; acesso venoso pérvio; manejo de náuseas e neutropenia.', alerta: 'Alta vigilância: extravasamento de vesicantes; descarte de resíduos citotóxicos; teratogênicos.' },
    L1A: { mec: 'Agentes alquilantes (ciclofosfamida, ifosfamida, cisplatina etc.): lesam o DNA tumoral.', ae: 'Náuseas e vômitos intensos, mielossupressão, alopecia; cistite hemorrágica (ciclofosfamida/ifosfamida).', enf: 'Pré-medicação antiemética; hidratação; mesna quando prescrita; controle de diurese.', alerta: 'Nefrotoxicidade e ototoxicidade (cisplatina); manuseio citotóxico.' },
    L1B: { mec: 'Antimetabólitos (metotrexato, fluoruracila, citarabina, gencitabina): bloqueiam a síntese de DNA.', ae: 'Mucosite, diarreia, mielossupressão, síndrome mão-pé.', enf: 'Higiene oral; hemograma; resgate com ácido folínico quando prescrito (metotrexato).', alerta: 'Metotrexato oral semanal × diário: erro fatal; interação com AINE e sulfametoxazol.' },
    L1D: { mec: 'Antibióticos antitumorais (doxorrubicina, bleomicina etc.).', ae: 'Mielossupressão, alopecia, urina avermelhada (antraciclinas).', enf: 'Acesso seguro e testado (vesicantes); orientar coloração da urina.', alerta: 'Cardiotoxicidade cumulativa (antraciclinas); toxicidade pulmonar (bleomicina).' },
    L1G: { mec: 'Anticorpos monoclonais antineoplásicos: ligam-se a alvos específicos das células tumorais ou do sistema imune.', ae: 'Reações infusionais (febre, calafrios, hipotensão), fadiga, alterações cutâneas.', enf: 'Pré-medicação conforme protocolo; velocidade de infusão escalonada; observar a primeira infusão.', alerta: 'Reações infusionais graves; cardiotoxicidade (anti-HER2).' },
    L1G5: { mec: 'Inibidores de checkpoint imune (anti-PD-1/PD-L1): liberam a resposta imune contra o tumor.', ae: 'Fadiga, exantema, diarreia, alterações tireoidianas.', enf: 'Orientar relatar diarreia, tosse, alteração urinária ou cansaço intenso: podem ser efeitos imunomediados.', alerta: 'Colite, pneumonite, hepatite e endocrinopatias imunomediadas (podem surgir meses depois).' },
    L1H: { mec: 'Inibidores de proteína quinase (orais, em geral): bloqueiam vias de sinalização do crescimento tumoral.', ae: 'Diarreia, exantema, fadiga, hipertensão, alterações hepáticas.', enf: 'Orientar horários e relação com alimentos; manuseio seguro de comprimidos citotóxicos.', alerta: 'Muitas interações por CYP3A4; prolongamento do QT com alguns agentes.' },
    L2B2: { mec: 'Antiandrogênicos (bicalutamida, enzalutamida, abiraterona): bloqueiam o estímulo hormonal no câncer de próstata.', ae: 'Ondas de calor, ginecomastia, fadiga, hipertensão (abiraterona).', enf: 'Monitorar PA e glicemia conforme o fármaco.', alerta: 'Hepatotoxicidade; abiraterona com corticoide associado.' },
    L3A9: { mec: 'Imunoestimulantes (exceto interferonas).', ae: 'Reação local, sintomas gripais.', enf: 'Conservar refrigerado conforme rótulo.', alerta: 'Seguir protocolo da especialidade.' },
    L4B: { mec: 'Anti-TNF (adalimumabe, infliximabe, etanercepte): bloqueiam o fator de necrose tumoral.', ae: 'Reações no local ou à infusão, infecções respiratórias.', enf: 'Rastrear tuberculose latente e hepatite B antes; orientar sinais de infecção; não aplicar vacinas vivas.', alerta: 'Reativação de tuberculose; infecções graves.' },
    L4C: { mec: 'Inibidores de interleucinas (IL-6, IL-17, IL-12/23 etc.): imunobiológicos para doenças autoimunes.', ae: 'Infecções, reações no local de aplicação.', enf: 'Rastreio de infecções antes; técnica de autoaplicação; conservação refrigerada.', alerta: 'Infecções oportunistas; vacinas vivas contraindicadas.' },
    B6D: { mec: 'Medicamentos para angioedema hereditário (inibidor de C1, icatibanto).', ae: 'Reação no local de aplicação.', enf: 'Ensinar autoaplicação para crises.', alerta: 'Edema de laringe: emergência — adrenalina e anti-histamínicos têm pouco efeito nesse tipo de angioedema.' },
    V3F: { mec: 'Quelantes de ferro (deferoxamina, deferasirox).', ae: 'Desconforto GI, alterações renais e auditivas.', enf: 'Infusão SC lenta (deferoxamina); exames periódicos.', alerta: 'Nefrotoxicidade; alterações visuais e auditivas.' },
    H4C: { mec: 'Hormônio do crescimento (somatropina).', ae: 'Reação no local, edema, artralgia.', enf: 'Aplicação SC noturna com rodízio; conservação refrigerada.', alerta: 'Hiperglicemia; hipertensão intracraniana benigna.' }
  };
  function perfil(cc) { if (!cc) return null; for (var n = cc.length; n >= 2; n--) { var p = P[cc.slice(0, n)]; if (p) return p; } return null; }
  var api = { PERFIS: P, perfil: perfil };
  if (typeof module !== 'undefined' && module.exports) module.exports = api;
  else root.Perfis = api;
})(this);
